84	func cmdQuery(dataFile string, argv []string, stdout, stderr io.Writer) int {
85		fs := newFlagSet("query", stderr)
86		fs.StringVar(&dataFile, "data", dataFile, "本地台账数据文件路径")
87		id := fs.String("id", "", "要查询的包裹编号")
88		if ok, code := parseFlags(fs, argv, stdout, stderr, printQueryHelp); !ok {
89			return code
90		}
91	
92		cleanIDVal, err := cleanID("包裹编号", *id)
93		if err != nil {
94			fmt.Fprintf(stderr, "%s query: %v\n", appName, err)
95			return exitBusiness
96		}
97	
98		store, err := Open(dataFile)
99		if err != nil {
100			fmt.Fprintf(stderr, "%s query: %v\n", appName, err)
101			return exitBusiness
102		}
103		p, err := store.Query(cleanIDVal)
104		if err != nil {
105			fmt.Fprintf(stderr, "%s query: %v\n", appName, err)
106			return exitBusiness
107		}
108	
109		fmt.Fprintf(stdout, "包裹编号: %s\n当前站点: %s\n当前状态: %s\n", p.ID, p.Station, p.Status)
110		if p.Status == statusDelivering {
111			for i := len(p.Trail) - 1; i >= 0; i-- {
112				if e := p.Trail[i]; e.Op == "出站" || e.Op == "续接" {
113					fmt.Fprintf(stdout, "当前批次: %s\n当前配送员: %s\n", e.Batch, e.Courier)
114					break
115				}
116			}
117		}
118		if sh := store.ActiveShipment(cleanIDVal); sh != nil {
119			fmt.Fprintf(stdout, "当前运输单: %s\n目的站: %s\n", sh.Shipment, sh.To)
120		}
121		if f := store.ActiveFreeze(cleanIDVal); f != nil {
122			fmt.Fprintf(stdout, "当前未解除异常: 异常单号: %s    原因: %s    冻结时间: %s\n",
123				f.Incident, f.Reason, f.Time.Format(timeFmt))
124		}
125		fmt.Fprintf(stdout, "轨迹（按提交顺序，共 %d 条）:\n", len(p.Trail))
126		for i, e := range p.Trail {
127			switch e.Op {
128			case "退回":
129				fmt.Fprintf(stdout, "  %d. 操作: 退回    源站: %s    目的站: %s    退回请求号: %s    原交接请求号: %s    原因: %s    时间: %s\n",
130					i+1, e.From, e.Station, e.Request, e.RefRequest, e.Reason, e.Time.Format(timeFmt))
131			case "出站":
132				fmt.Fprintf(stdout, "  %d. 操作: 出站    站点: %s    批次号: %s    配送员: %s    时间: %s\n",
133					i+1, e.Station, e.Batch, e.Courier, e.Time.Format(timeFmt))
134			case "回执":
135				revoked := ""
136				if rc := store.ReceiptOf(e.Request); rc != nil && rc.RevokedBy != "" {
137					revoked = fmt.Sprintf("    撤销状态: 已撤销（撤销请求号: %s）", rc.RevokedBy)
138				}
139				if e.Result == resultFailed {
140					fmt.Fprintf(stdout, "  %d. 操作: 回执    站点: %s    批次号: %s    结果: %s    原因: %s    请求号: %s    时间: %s%s\n",
141						i+1, e.Station, e.Batch, e.Result, e.Reason, e.Request, e.Time.Format(timeFmt), revoked)
142				} else {
143					fmt.Fprintf(stdout, "  %d. 操作: 回执    站点: %s    批次号: %s    结果: %s    请求号: %s    时间: %s%s\n",
144						i+1, e.Station, e.Batch, e.Result, e.Request, e.Time.Format(timeFmt), revoked)
145				}
146			case "撤销回执":
147				fmt.Fprintf(stdout, "  %d. 操作: 撤销回执    站点: %s    批次号: %s    撤销请求号: %s    原回执请求号: %s    原因: %s    时间: %s\n",
148					i+1, e.Station, e.Batch, e.Request, e.RefRequest, e.Reason, e.Time.Format(timeFmt))
149			case "冻结":
150				fmt.Fprintf(stdout, "  %d. 操作: 冻结    站点: %s    异常单号: %s    原因: %s    时间: %s\n",
151					i+1, e.Station, e.Incident, e.Reason, e.Time.Format(timeFmt))
152			case "解除冻结":
153				fmt.Fprintf(stdout, "  %d. 操作: 解除冻结    站点: %s    异常单号: %s    解除请求号: %s    处理说明: %s    时间: %s\n",
154					i+1, e.Station, e.Incident, e.Request, e.Note, e.Time.Format(timeFmt))
155			case "收回":
156				fmt.Fprintf(stdout, "  %d. 操作: 收回    站点: %s    批次号: %s    中止请求号: %s    原因: %s    时间: %s\n",
157					i+1, e.Station, e.Batch, e.Request, e.Reason, e.Time.Format(timeFmt))
158			case "续接":
159				fmt.Fprintf(stdout, "  %d. 操作: 续接    站点: %s    原批次号: %s    新批次号: %s    新配送员: %s    续接请求号: %s    原因: %s    时间: %s\n",
160					i+1, e.Station, e.FromBatch, e.Batch, e.Courier, e.Request, e.Reason, e.Time.Format(timeFmt))
161			case "发运":
162				fmt.Fprintf(stdout, "  %d. 操作: 发运    源站: %s    目的站: %s    运输单号: %s    时间: %s\n",
163					i+1, e.From, e.To, e.Shipment, e.Time.Format(timeFmt))
164			case "接收":
165				fmt.Fprintf(stdout, "  %d. 操作: 接收    源站: %s    目的站: %s    运输单号: %s    接收请求号: %s    时间: %s\n",
166					i+1, e.From, e.To, e.Shipment, e.Request, e.Time.Format(timeFmt))
167			default:
168				req := e.Request
169				if req == "" {
170					req = "-"
171				}
172				fmt.Fprintf(stdout, "  %d. 操作: %s    站点: %s    请求号: %s    时间: %s\n",
173					i+1, e.Op, e.Station, req, e.Time.Format(timeFmt))
174			}
175		}
176		return exitOK
177	}
