	fmt.Fprintf(stdout, "%s\n异常单号: %s\n包裹编号: %s\n所在站点: %s\n当前状态: %s\n异常原因: %s\n发生时间: %s\n",
		headline, res.Incident, res.Parcel, res.Station, cur.Status, res.Reason, res.Time.Format(timeFmt))
	return exitOK
}

