334	// validate 校验载入内容内部自洽，防止损坏数据被当作有效台账继续使用。
335	func (l *ledgerFile) validate() error {
336		for id, p := range l.Parcels {
337			if p == nil || id != p.ID || p.Station == "" || p.Status == "" || len(p.Trail) == 0 {
338				return fmt.Errorf("%w: 包裹 %q 记录不完整", ErrCorrupt, id)
339			}
340			switch p.Status {
341			case statusInStation, statusDelivering, statusSigned, statusFrozen, statusInTransit:
342			default:
343				return fmt.Errorf("%w: 包裹 %q 的状态 %q 不受支持", ErrCorrupt, id, p.Status)
344			}
345			for i, e := range p.Trail {
346				if e.Op == "" || e.Station == "" || e.Time.IsZero() {
347					return fmt.Errorf("%w: 包裹 %q 第 %d 条轨迹缺少操作、站点或发生时间", ErrCorrupt, id, i+1)
348				}
349				if e.Op == "退回" {
350					if e.Request == "" || e.Reason == "" || e.From == "" {
351						return fmt.Errorf("%w: 包裹 %q 第 %d 条退回轨迹缺少退回请求号、源站或原因", ErrCorrupt, id, i+1)
352					}
353					if _, ok := l.Handoffs[e.RefRequest]; !ok {
354						return fmt.Errorf("%w: 包裹 %q 第 %d 条退回轨迹引用了不存在的原交接 %q", ErrCorrupt, id, i+1, e.RefRequest)
355					}
356				}
357				if e.Op == "出站" {
358					if e.Batch == "" || e.Courier == "" {
359						return fmt.Errorf("%w: 包裹 %q 第 %d 条出站轨迹缺少批次号或配送员", ErrCorrupt, id, i+1)
360					}
361					if _, ok := l.Batches[e.Batch]; !ok {
362						return fmt.Errorf("%w: 包裹 %q 第 %d 条出站轨迹引用了不存在的批次 %q", ErrCorrupt, id, i+1, e.Batch)
363					}
364				}
365				if e.Op == "回执" {
366					if e.Batch == "" || e.Request == "" || (e.Result != resultSigned && e.Result != resultFailed) {
367						return fmt.Errorf("%w: 包裹 %q 第 %d 条回执轨迹缺少批次号、请求号或结果无效", ErrCorrupt, id, i+1)
368					}
369					if e.Result == resultFailed && e.Reason == "" {
370						return fmt.Errorf("%w: 包裹 %q 第 %d 条失败回执轨迹缺少原因", ErrCorrupt, id, i+1)
371					}
372					if _, ok := l.Batches[e.Batch]; !ok {
373						return fmt.Errorf("%w: 包裹 %q 第 %d 条回执轨迹引用了不存在的批次 %q", ErrCorrupt, id, i+1, e.Batch)
374					}
375				}
376				if e.Op == "撤销回执" {
377					if e.Batch == "" || e.Request == "" || e.RefRequest == "" || e.Reason == "" {
378						return fmt.Errorf("%w: 包裹 %q 第 %d 条撤销回执轨迹缺少批次号、撤销请求号、原回执请求号或原因", ErrCorrupt, id, i+1)
379					}
380					b, ok := l.Batches[e.Batch]
381					if !ok || b == nil {
382						return fmt.Errorf("%w: 包裹 %q 第 %d 条撤销回执轨迹引用了不存在的批次 %q", ErrCorrupt, id, i+1, e.Batch)
383					}
384					if e.Station != b.Station {
385						return fmt.Errorf("%w: 包裹 %q 第 %d 条撤销回执轨迹的站点 %q 与批次 %q 出发站 %q 不一致",
386							ErrCorrupt, id, i+1, e.Station, e.Batch, b.Station)
387					}
388					rv, ok := l.Revokes[e.Request]
389					if !ok || rv == nil {
390						return fmt.Errorf("%w: 包裹 %q 第 %d 条撤销回执轨迹引用了不存在的撤销请求 %q", ErrCorrupt, id, i+1, e.Request)
391					}
392					if rv.Receipt != e.RefRequest || rv.Batch != e.Batch || rv.Parcel != id || rv.Reason != e.Reason || !rv.Time.Equal(e.Time) {
393						return fmt.Errorf("%w: 包裹 %q 第 %d 条撤销回执轨迹与撤销请求 %q 记录不一致", ErrCorrupt, id, i+1, e.Request)
394					}
395				}
396				if e.Op == "收回" {
397					if e.Batch == "" || e.Request == "" || e.Reason == "" {
398						return fmt.Errorf("%w: 包裹 %q 第 %d 条收回轨迹缺少批次号、中止请求号或原因", ErrCorrupt, id, i+1)
399					}
400					a, ok := l.Aborts[e.Request]
401					if !ok || a == nil {
402						return fmt.Errorf("%w: 包裹 %q 第 %d 条收回轨迹引用了不存在的中止请求 %q", ErrCorrupt, id, i+1, e.Request)
403					}
404					if a.Batch != e.Batch || a.Station != e.Station || a.Reason != e.Reason || !a.Time.Equal(e.Time) {
405						return fmt.Errorf("%w: 包裹 %q 第 %d 条收回轨迹与中止请求 %q 记录不一致", ErrCorrupt, id, i+1, e.Request)
406					}
407					inAbort := false
408					for _, pid := range a.Parcels {
409						if pid == id {
410							inAbort = true
411							break
412						}
413					}
414					if !inAbort {
415						return fmt.Errorf("%w: 包裹 %q 第 %d 条收回轨迹不在中止请求 %q 的收回集合中", ErrCorrupt, id, i+1, e.Request)
416					}
417				}
418				if e.Op == "续接" {
419					if e.Batch == "" || e.FromBatch == "" || e.Courier == "" || e.Request == "" || e.Reason == "" {
420						return fmt.Errorf("%w: 包裹 %q 第 %d 条续接轨迹缺少新批次号、原批次号、新配送员、续接请求号或原因", ErrCorrupt, id, i+1)
421					}
422					t, ok := l.Transfers[e.Request]
423					if !ok || t == nil {
424						return fmt.Errorf("%w: 包裹 %q 第 %d 条续接轨迹引用了不存在的续接请求 %q", ErrCorrupt, id, i+1, e.Request)
425					}
426					if t.FromBatch != e.FromBatch || t.ToBatch != e.Batch || t.ToCourier != e.Courier ||
427						t.Station != e.Station || t.Reason != e.Reason || !t.Time.Equal(e.Time) {
428						return fmt.Errorf("%w: 包裹 %q 第 %d 条续接轨迹与续接请求 %q 记录不一致", ErrCorrupt, id, i+1, e.Request)
429					}
430					inTransfer := false
431					for _, pid := range t.Parcels {
432						if pid == id {
433							inTransfer = true
434							break
435						}
436					}
437					if !inTransfer {
438						return fmt.Errorf("%w: 包裹 %q 第 %d 条续接轨迹不在续接请求 %q 的转交集合中", ErrCorrupt, id, i+1, e.Request)
439					}
440				}
441				if e.Op == "发运" {
442					if e.Shipment == "" || e.From == "" || e.To == "" {
443						return fmt.Errorf("%w: 包裹 %q 第 %d 条发运轨迹缺少运输单号、源站或目的站", ErrCorrupt, id, i+1)
444					}
445					sh, ok := l.Shipments[e.Shipment]
446					if !ok || sh == nil {
447						return fmt.Errorf("%w: 包裹 %q 第 %d 条发运轨迹引用了不存在的运输单 %q", ErrCorrupt, id, i+1, e.Shipment)
448					}
449					if sh.From != e.From || sh.To != e.To || e.Station != e.From || !sh.Time.Equal(e.Time) {
450						return fmt.Errorf("%w: 包裹 %q 第 %d 条发运轨迹与运输单 %q 记录不一致", ErrCorrupt, id, i+1, e.Shipment)
451					}
452					inShipment := false
453					for _, pid := range sh.Parcels {
454						if pid == id {
455							inShipment = true
456							break
457						}
458					}
459					if !inShipment {
460						return fmt.Errorf("%w: 包裹 %q 第 %d 条发运轨迹不在运输单 %q 的成员集合中", ErrCorrupt, id, i+1, e.Shipment)
461					}
462				}
463				if e.Op == "接收" {
464					if e.Shipment == "" || e.Request == "" || e.From == "" || e.To == "" {
465						return fmt.Errorf("%w: 包裹 %q 第 %d 条接收轨迹缺少运输单号、接收请求号、源站或目的站", ErrCorrupt, id, i+1)
466					}
467					rv, ok := l.Receives[e.Request]
468					if !ok || rv == nil {
469						return fmt.Errorf("%w: 包裹 %q 第 %d 条接收轨迹引用了不存在的接收请求 %q", ErrCorrupt, id, i+1, e.Request)
470					}
471					if rv.Shipment != e.Shipment || rv.Station != e.Station || e.Station != e.To || !rv.Time.Equal(e.Time) {
472						return fmt.Errorf("%w: 包裹 %q 第 %d 条接收轨迹与接收请求 %q 记录不一致", ErrCorrupt, id, i+1, e.Request)
473					}
474					sh, ok := l.Shipments[e.Shipment]
475					if !ok || sh == nil {
476						return fmt.Errorf("%w: 包裹 %q 第 %d 条接收轨迹引用了不存在的运输单 %q", ErrCorrupt, id, i+1, e.Shipment)
477					}
478					if sh.From != e.From || sh.To != e.To {
479						return fmt.Errorf("%w: 包裹 %q 第 %d 条接收轨迹的源站或目的站与运输单 %q 记录（%q -> %q）不一致",
480							ErrCorrupt, id, i+1, e.Shipment, sh.From, sh.To)
481					}
482					inReceive := false
483					for _, pid := range rv.Parcels {
484						if pid == id {
485							inReceive = true
486							break
487						}
488					}
489					if !inReceive {
490						return fmt.Errorf("%w: 包裹 %q 第 %d 条接收轨迹不在接收请求 %q 的成员集合中", ErrCorrupt, id, i+1, e.Request)
491					}
492				}
493				if e.Op == "冻结" {
494					if e.Incident == "" || e.Reason == "" {
495						return fmt.Errorf("%w: 包裹 %q 第 %d 条冻结轨迹缺少异常单号或原因", ErrCorrupt, id, i+1)
496					}
497					f, ok := l.Freezes[e.Incident]
498					if !ok || f == nil {
499						return fmt.Errorf("%w: 包裹 %q 第 %d 条冻结轨迹引用了不存在的异常单 %q", ErrCorrupt, id, i+1, e.Incident)
500					}
501					if f.Parcel != id || f.Reason != e.Reason || f.Station != e.Station || !f.Time.Equal(e.Time) {
502						return fmt.Errorf("%w: 包裹 %q 第 %d 条冻结轨迹与异常单 %q 记录不一致", ErrCorrupt, id, i+1, e.Incident)
503					}
504				}
505				if e.Op == "解除冻结" {
506					if e.Incident == "" || e.Request == "" || e.Note == "" {
507						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除冻结轨迹缺少异常单号、解除请求号或处理说明", ErrCorrupt, id, i+1)
508					}
509					f, ok := l.Freezes[e.Incident]
510					if !ok || f == nil {
511						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除冻结轨迹引用了不存在的异常单 %q", ErrCorrupt, id, i+1, e.Incident)
512					}
513					if f.Parcel != id || f.Station != e.Station || f.ReleasedBy != e.Request {
514						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除冻结轨迹与异常单 %q 不匹配", ErrCorrupt, id, i+1, e.Incident)
515					}
516					u, ok := l.Unfreezes[e.Request]
517					if !ok || u == nil || u.Incident != e.Incident || u.Parcel != id || u.Note != e.Note || !u.Time.Equal(e.Time) {
518						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除冻结轨迹与解除请求 %q 记录不一致", ErrCorrupt, id, i+1, e.Request)
519					}
520				}
521			}
522		}
523		// 站间运输生命周期：按每件轨迹的保存顺序（不按发生时间排序）核对发运与接收的
524		// 配对关系。每张运输单的成员恰有一次对应发运；已接收时恰有一次对应接收且位于
525		// 发运之后；发运后到接收前不得出现其他作业轨迹；未接收时不得有接收记录，
526		// 发运必须是最后一条轨迹。
527		for id, p := range l.Parcels {
528			shipped := make(map[string]bool) // 该包裹轨迹中已出现发运的运输单号
529			var open string                  // 已发运、尚未在轨迹中接收的在途运输单号
530			for i, e := range p.Trail {
531				if open != "" && e.Op != "接收" {
532					return fmt.Errorf("%w: 包裹 %q 第 %d 条轨迹（%s）出现在运输单 %q 发运之后、接收之前，在途期间不得有其他作业轨迹",
533						ErrCorrupt, id, i+1, e.Op, open)
534				}
535				switch e.Op {
536				case "发运":
537					if shipped[e.Shipment] {
538						return fmt.Errorf("%w: 包裹 %q 第 %d 条轨迹重复发运运输单 %q，每张运输单的成员恰有一次对应发运",
539							ErrCorrupt, id, i+1, e.Shipment)
540					}
541					shipped[e.Shipment] = true
542					open = e.Shipment
543				case "接收":
544					if open == "" {
545						return fmt.Errorf("%w: 包裹 %q 第 %d 条接收轨迹（运输单 %q）位于对应发运之前或缺少对应发运",
546							ErrCorrupt, id, i+1, e.Shipment)
547					}
548					if e.Shipment != open {
549						return fmt.Errorf("%w: 包裹 %q 第 %d 条接收轨迹的运输单 %q 与当前在途运输单 %q 不匹配",
550							ErrCorrupt, id, i+1, e.Shipment, open)
551					}
552					open = ""
553				}
554			}
555			if open != "" {
556				sh := l.Shipments[open] // 发运轨迹校验已保证运输单存在且非空
557				if sh.ReceivedBy != "" {
558					return fmt.Errorf("%w: 包裹 %q 的运输单 %q 已接收（接收请求号 %q），但轨迹缺少对应的接收记录",
559						ErrCorrupt, id, open, sh.ReceivedBy)
560				}
561			}
562		}
563		// 当前归属与状态必须由轨迹记录形成：按保存顺序的最后一条轨迹推导应有的归属
564		// 站点与状态，与台账当前值不一致即存在无对应记录的站点或状态改变。接收后的
565		// 合法后续流转（交接、再次发运、回执及其撤销、收回、续接、冻结与解除）会
566		// 产生新的末条轨迹，按新轨迹校验，不因历史接收而把成员固定在目的站。
567		for id, p := range l.Parcels {
568			last := p.Trail[len(p.Trail)-1]
569			var want string
570			switch last.Op {
571			case "收件", "交接", "退回", "收回", "接收", "解除冻结":
572				want = statusInStation
573			case "出站", "续接", "撤销回执":
574				want = statusDelivering
575			case "回执":
576				if last.Result == resultSigned {
577					want = statusSigned
578				} else {
579					want = statusInStation
580				}
581			case "冻结":
582				want = statusFrozen
583			case "发运":
584				want = statusInTransit
585			default:
586				continue // 未知操作不参与推导（逐条校验已兜底）
587			}
588			if p.Station != last.Station || p.Status != want {
589				return fmt.Errorf("%w: 包裹 %q 当前归属 %q、状态 %q 与最后一条轨迹（%s，站点 %q）应形成的归属与状态 %q、%q 不一致",
590					ErrCorrupt, id, p.Station, p.Status, last.Op, last.Station, last.Station, want)
591			}
592		}
593		for req, h := range l.Handoffs {
594			if h == nil || req != h.Request || h.From == "" || h.To == "" || len(h.Parcels) == 0 {
595				return fmt.Errorf("%w: 请求号 %q 的交接结果不完整", ErrCorrupt, req)
596			}
597			for _, id := range h.Parcels {
598				if _, ok := l.Parcels[id]; !ok {
599					return fmt.Errorf("%w: 请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, id)
600				}
601			}
602			if h.ReturnedBy != "" {
603				r, ok := l.Returns[h.ReturnedBy]
604				if !ok || r == nil || r.Handoff != req {
605					return fmt.Errorf("%w: 交接 %q 标记的退回请求号 %q 无法对应", ErrCorrupt, req, h.ReturnedBy)
606				}
607			}
608		}
609		for req, r := range l.Returns {
610			if r == nil || req != r.Request || r.Handoff == "" || r.From == "" || r.To == "" ||
611				r.Reason == "" || len(r.Parcels) == 0 || r.Time.IsZero() {
612				return fmt.Errorf("%w: 退回请求号 %q 的退回结果不完整", ErrCorrupt, req)
613			}
614			h, ok := l.Handoffs[r.Handoff]
615			if !ok || h == nil {
616				return fmt.Errorf("%w: 退回请求号 %q 引用了不存在的原交接 %q", ErrCorrupt, req, r.Handoff)
617			}
618			if h.ReturnedBy != req || r.From != h.To || r.To != h.From || !sameSet(r.Parcels, h.Parcels) {
619				return fmt.Errorf("%w: 退回请求号 %q 与原交接 %q 的记录不一致", ErrCorrupt, req, r.Handoff)
620			}
621			for _, id := range r.Parcels {
622				if _, ok := l.Parcels[id]; !ok {
623					return fmt.Errorf("%w: 退回请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, id)
624				}
625			}
626		}
627		for id, b := range l.Batches {
628			if b == nil || id != b.Batch || b.Station == "" || b.Courier == "" || len(b.Parcels) == 0 || b.Time.IsZero() {
629				return fmt.Errorf("%w: 批次号 %q 的出站结果不完整", ErrCorrupt, id)
630			}
631			seen := make(map[string]bool, len(b.Parcels))
632			for _, pid := range b.Parcels {
633				if seen[pid] {
634					return fmt.Errorf("%w: 批次 %q 的成员 %q 重复", ErrCorrupt, id, pid)
635				}
636				seen[pid] = true
637				if _, ok := l.Parcels[pid]; !ok {
638					return fmt.Errorf("%w: 批次 %q 引用了不存在的包裹 %q", ErrCorrupt, id, pid)
639				}
640			}
641			for pid, e := range b.Receipts {
642				if e == nil || !seen[pid] || e.Request == "" || e.Time.IsZero() ||
643					(e.Result != resultSigned && e.Result != resultFailed) ||
644					(e.Result == resultFailed && e.Reason == "") || (e.Result == resultSigned && e.Reason != "") {
645					return fmt.Errorf("%w: 批次 %q 中包裹 %q 的回执记录不完整", ErrCorrupt, id, pid)
646				}
647				rc, ok := l.Receipts[e.Request]
648				if !ok || rc == nil || rc.Batch != id || rc.Parcel != pid {
649					return fmt.Errorf("%w: 批次 %q 中包裹 %q 的回执请求号 %q 无法对应", ErrCorrupt, id, pid, e.Request)
650				}
651				if e.RevokedBy != rc.RevokedBy {
652					return fmt.Errorf("%w: 批次 %q 中包裹 %q 的回执条目与回执请求号 %q 的撤销标记不一致", ErrCorrupt, id, pid, e.Request)
653				}
654			}
655			if b.AbortedBy != "" {
656				a, ok := l.Aborts[b.AbortedBy]
657				if !ok || a == nil || a.Batch != id {
658					return fmt.Errorf("%w: 批次 %q 标记的中止请求号 %q 无法对应", ErrCorrupt, id, b.AbortedBy)
659				}
660			}
661			if b.TransferredBy != "" {
662				if b.AbortedBy != "" {
663					return fmt.Errorf("%w: 批次 %q 不能同时标记中止与转交", ErrCorrupt, id)
664				}
665				t, ok := l.Transfers[b.TransferredBy]
666				if !ok || t == nil || t.FromBatch != id {
667					return fmt.Errorf("%w: 批次 %q 标记的续接请求号 %q 无法对应", ErrCorrupt, id, b.TransferredBy)
668				}
669			}
670			if b.RelayedFrom != "" {
671				t, ok := l.Transfers[b.RelayRequest]
672				if !ok || t == nil || t.ToBatch != id || t.FromBatch != b.RelayedFrom {
673					return fmt.Errorf("%w: 批次 %q 标记的续接来源（原批次=%q 续接请求号=%q）无法对应",
674						ErrCorrupt, id, b.RelayedFrom, b.RelayRequest)
675				}
676			} else if b.RelayRequest != "" {
677				return fmt.Errorf("%w: 批次 %q 标记了续接请求号 %q 但缺少来源批次", ErrCorrupt, id, b.RelayRequest)
678			}
679		}
680		for req, rc := range l.Receipts {
681			if rc == nil || req != rc.Request || rc.Batch == "" || rc.Parcel == "" || rc.Time.IsZero() ||
682				(rc.Result != resultSigned && rc.Result != resultFailed) ||
683				(rc.Result == resultFailed && rc.Reason == "") || (rc.Result == resultSigned && rc.Reason != "") {
684				return fmt.Errorf("%w: 回执请求号 %q 的回执结果不完整", ErrCorrupt, req)
685			}
686			b, ok := l.Batches[rc.Batch]
687			if !ok || b == nil {
688				return fmt.Errorf("%w: 回执请求号 %q 引用了不存在的批次 %q", ErrCorrupt, req, rc.Batch)
689			}
690			// 每件包裹的当前回执条目一旦建立只会被新回执取代、不会删除，
691			// 因此该件在批次内必须始终有一条回执条目。
692			e, cur := b.Receipts[rc.Parcel]
693			if !cur {
694				return fmt.Errorf("%w: 回执请求号 %q 在批次 %q 中缺少包裹 %q 的回执条目", ErrCorrupt, req, rc.Batch, rc.Parcel)
695			}
696			if rc.RevokedBy == "" {
697				// 未撤销回执必须仍是该件在该批次的当前有效回执。
698				if e.Request != req || e.Result != rc.Result || e.Reason != rc.Reason || !e.Time.Equal(rc.Time) || e.RevokedBy != "" {
699					return fmt.Errorf("%w: 回执请求号 %q 与批次 %q 的回执记录不一致", ErrCorrupt, req, rc.Batch)
700				}
701				continue
702			}
703			// 已撤销回执：撤销关联必须存在且回指该回执。
704			rv, ok := l.Revokes[rc.RevokedBy]
705			if !ok || rv == nil || rv.Receipt != req {
706				return fmt.Errorf("%w: 回执请求号 %q 标记的撤销请求号 %q 无法对应", ErrCorrupt, req, rc.RevokedBy)
707			}
708			if e.Request == req {
709				// 该件之后未重新回执：批次内条目必须同内容并同样标记撤销。
710				if e.Result != rc.Result || e.Reason != rc.Reason || !e.Time.Equal(rc.Time) || e.RevokedBy != rc.RevokedBy {
711					return fmt.Errorf("%w: 回执请求号 %q 与批次 %q 的回执记录不一致", ErrCorrupt, req, rc.Batch)
712				}
713			}
714			// 该件之后已用新请求号重新回执：当前条目属于新回执，由其自身校验。
715		}
716		// 撤销：每条撤销必须对应一条已撤销回执，批次、包裹一致，且包裹轨迹中有
717		// 与该撤销请求一致的撤销回执记录；撤销关联缺失或不一致即损坏。
718		for req, rv := range l.Revokes {
719			if rv == nil || req != rv.Request || rv.Receipt == "" || rv.Batch == "" || rv.Parcel == "" ||
720				rv.Reason == "" || rv.Time.IsZero() {
721				return fmt.Errorf("%w: 撤销请求号 %q 的撤销结果不完整", ErrCorrupt, req)
722			}
723			rc, ok := l.Receipts[rv.Receipt]
724			if !ok || rc == nil {
725				return fmt.Errorf("%w: 撤销请求号 %q 引用了不存在的原回执 %q", ErrCorrupt, req, rv.Receipt)
726			}
727			if rc.RevokedBy != req {
728				return fmt.Errorf("%w: 撤销请求号 %q 与原回执 %q 的撤销标记不一致", ErrCorrupt, req, rv.Receipt)
729			}
730			if rc.Batch != rv.Batch || rc.Parcel != rv.Parcel {
731				return fmt.Errorf("%w: 撤销请求号 %q 的批次或包裹与原回执 %q 不一致", ErrCorrupt, req, rv.Receipt)
732			}
733			p, ok := l.Parcels[rv.Parcel]
734			if !ok {
735				return fmt.Errorf("%w: 撤销请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, rv.Parcel)
736			}
737			found := false
738			for _, e := range p.Trail {
739				if e.Op == "撤销回执" && e.Request == req {
740					found = true
741					break
742				}
743			}
744			if !found {
745				return fmt.Errorf("%w: 撤销请求号 %q 的包裹 %q 缺少对应的撤销回执轨迹", ErrCorrupt, req, rv.Parcel)
746			}
747		}
748		// 中止：收回集合必须恰为原批次的未回执成员（按原成员顺序，已撤销回执不计入
749		// 有效回执），且每件收回包裹的轨迹中都有与该中止请求一致的收回记录；
750		// 中止记录与收回轨迹不一致即损坏。
751		for req, a := range l.Aborts {
752			if a == nil || req != a.Request || a.Batch == "" || a.Station == "" || a.Reason == "" ||
753				len(a.Parcels) == 0 || a.Time.IsZero() {
754				return fmt.Errorf("%w: 中止请求号 %q 的中止结果不完整", ErrCorrupt, req)
755			}
756			b, ok := l.Batches[a.Batch]
757			if !ok || b == nil {
758				return fmt.Errorf("%w: 中止请求号 %q 引用了不存在的批次 %q", ErrCorrupt, req, a.Batch)
759			}
760			if b.AbortedBy != req {
761				return fmt.Errorf("%w: 中止请求号 %q 与批次 %q 的中止标记不一致", ErrCorrupt, req, a.Batch)
762			}
763			if a.Station != b.Station {
764				return fmt.Errorf("%w: 中止请求号 %q 的站点 %q 与批次 %q 出发站 %q 不一致", ErrCorrupt, req, a.Station, a.Batch, b.Station)
765			}
766			expect := make([]string, 0, len(b.Parcels))
767			for _, pid := range b.Parcels {
768				if e, done := b.Receipts[pid]; !done || e.RevokedBy != "" {
769					expect = append(expect, pid)
770				}
771			}
772			if len(expect) != len(a.Parcels) {
773				return fmt.Errorf("%w: 中止请求号 %q 的收回集合与批次 %q 的未回执成员不一致", ErrCorrupt, req, a.Batch)
774			}
775			for i := range expect {
776				if expect[i] != a.Parcels[i] {
777					return fmt.Errorf("%w: 中止请求号 %q 的收回集合与批次 %q 的未回执成员不一致", ErrCorrupt, req, a.Batch)
778				}
779			}
780			for _, pid := range a.Parcels {
781				p, ok := l.Parcels[pid]
782				if !ok {
783					return fmt.Errorf("%w: 中止请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, pid)
784				}
785				found := false
786				for _, e := range p.Trail {
787					if e.Op == "收回" && e.Request == req {
788						found = true
789						break
790					}
791				}
792				if !found {
793					return fmt.Errorf("%w: 中止请求号 %q 的收回包裹 %q 缺少对应的收回轨迹", ErrCorrupt, req, pid)
794				}
795			}
796		}
797		// 续接：转交集合必须恰为原批次的未回执成员（按原成员顺序），新批次必须由该续接
798		// 创建且成员、站点、配送员、接手时间与之一致；每件转交包裹的轨迹中都有与该
799		// 续接请求一致的续接记录；续接记录与批次及轨迹不一致即损坏。
800		for req, t := range l.Transfers {
801			if t == nil || req != t.Request || t.FromBatch == "" || t.ToBatch == "" || t.Station == "" ||
802				t.FromCourier == "" || t.ToCourier == "" || t.FromCourier == t.ToCourier ||
803				t.Reason == "" || len(t.Parcels) == 0 || t.Time.IsZero() {
804				return fmt.Errorf("%w: 续接请求号 %q 的续接结果不完整", ErrCorrupt, req)
805			}
806			fb, ok := l.Batches[t.FromBatch]
807			if !ok || fb == nil {
808				return fmt.Errorf("%w: 续接请求号 %q 引用了不存在的原批次 %q", ErrCorrupt, req, t.FromBatch)
809			}
810			if fb.TransferredBy != req {
811				return fmt.Errorf("%w: 续接请求号 %q 与原批次 %q 的转交标记不一致", ErrCorrupt, req, t.FromBatch)
812			}
813			if fb.Station != t.Station || fb.Courier != t.FromCourier {
814				return fmt.Errorf("%w: 续接请求号 %q 的站点或原配送员与原批次 %q 不一致", ErrCorrupt, req, t.FromBatch)
815			}
816			nb, ok := l.Batches[t.ToBatch]
817			if !ok || nb == nil {
818				return fmt.Errorf("%w: 续接请求号 %q 引用了不存在的新批次 %q", ErrCorrupt, req, t.ToBatch)
819			}
820			if nb.RelayedFrom != t.FromBatch || nb.RelayRequest != req {
821				return fmt.Errorf("%w: 续接请求号 %q 与新批次 %q 的来源标记不一致", ErrCorrupt, req, t.ToBatch)
822			}
823			if nb.Station != t.Station || nb.Courier != t.ToCourier || !nb.Time.Equal(t.Time) {
824				return fmt.Errorf("%w: 续接请求号 %q 与新批次 %q 的站点、配送员或接手时间不一致", ErrCorrupt, req, t.ToBatch)
825			}
826			expect := make([]string, 0, len(fb.Parcels))
827			for _, pid := range fb.Parcels {
828				if e, done := fb.Receipts[pid]; !done || e.RevokedBy != "" {
829					expect = append(expect, pid)
830				}
831			}
832			if !sameOrder(expect, t.Parcels) || !sameOrder(t.Parcels, nb.Parcels) {
833				return fmt.Errorf("%w: 续接请求号 %q 的转交集合与原批次 %q 的未回执成员或新批次 %q 的成员不一致",
834					ErrCorrupt, req, t.FromBatch, t.ToBatch)
835			}
836			for _, pid := range t.Parcels {
837				p, ok := l.Parcels[pid]
838				if !ok {
839					return fmt.Errorf("%w: 续接请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, pid)
840				}
841				found := false
842				for _, e := range p.Trail {
843					if e.Op == "续接" && e.Request == req {
844						found = true
845						break
846					}
847				}
848				if !found {
849					return fmt.Errorf("%w: 续接请求号 %q 的转交包裹 %q 缺少对应的续接轨迹", ErrCorrupt, req, pid)
850				}
851			}
852		}
853		// 发运：成员必须非空、不重复且都已登记，每件成员的轨迹中都有与该运输单一致的
854		// 发运记录；未接收运输单的成员必须仍归该单在途（状态为站间在途、归属源站），
855		// 且一件包裹同时只能属于一张未接收运输单；关联缺失或矛盾即损坏。
856		inTransitCount := make(map[string]int) // 包裹 -> 包含它的未接收运输单数
857		for no, sh := range l.Shipments {
858			if sh == nil || no != sh.Shipment || sh.From == "" || sh.To == "" || sh.From == sh.To ||
859				len(sh.Parcels) == 0 || sh.Time.IsZero() {
860				return fmt.Errorf("%w: 运输单号 %q 的发运结果不完整", ErrCorrupt, no)
861			}
862			seen := make(map[string]bool, len(sh.Parcels))
863			for _, pid := range sh.Parcels {
864				if seen[pid] {
865					return fmt.Errorf("%w: 运输单 %q 的成员 %q 重复", ErrCorrupt, no, pid)
866				}
867				seen[pid] = true
868				p, ok := l.Parcels[pid]
869				if !ok {
870					return fmt.Errorf("%w: 运输单 %q 引用了不存在的包裹 %q", ErrCorrupt, no, pid)
871				}
872				found := false
873				for _, e := range p.Trail {
874					if e.Op == "发运" && e.Shipment == no {
875						found = true
876						break
877					}
878				}
879				if !found {
880					return fmt.Errorf("%w: 运输单 %q 的成员包裹 %q 缺少对应的发运轨迹", ErrCorrupt, no, pid)
881				}
882			}
883			if sh.ReceivedBy != "" {
884				r, ok := l.Receives[sh.ReceivedBy]
885				if !ok || r == nil || r.Shipment != no {
886					return fmt.Errorf("%w: 运输单 %q 标记的接收请求号 %q 无法对应", ErrCorrupt, no, sh.ReceivedBy)
887				}
888				continue
889			}
890			for _, pid := range sh.Parcels {
891				p := l.Parcels[pid]
892				inTransitCount[pid]++
893				if p.Status != statusInTransit || p.Station != sh.From {
894					return fmt.Errorf("%w: 运输单 %q 尚未接收，但成员包裹 %q 当前归属 %q、状态 %q，不在该单在途",
895						ErrCorrupt, no, pid, p.Station, p.Status)
896				}
897			}
898		}
899		for id, p := range l.Parcels {
900			if p.Status == statusInTransit && inTransitCount[id] != 1 {
901				return fmt.Errorf("%w: 包裹 %q 当前为站间在途，但未接收运输单数为 %d，应恰好属于一张未接收运输单",
902					ErrCorrupt, id, inTransitCount[id])
903			}
904		}
905		// 接收：接收站点必须等于运输单目的站，成员必须恰为运输单原成员（按发运保存顺序），
906		// 且每件成员的轨迹中都有与该接收请求一致的接收记录；关联缺失或矛盾即损坏。
907		for req, r := range l.Receives {
908			if r == nil || req != r.Request || r.Shipment == "" || r.Station == "" || len(r.Parcels) == 0 || r.Time.IsZero() {
909				return fmt.Errorf("%w: 接收请求号 %q 的接收结果不完整", ErrCorrupt, req)
910			}
911			sh, ok := l.Shipments[r.Shipment]
912			if !ok || sh == nil {
913				return fmt.Errorf("%w: 接收请求号 %q 引用了不存在的运输单 %q", ErrCorrupt, req, r.Shipment)
914			}
915			if sh.ReceivedBy != req {
916				return fmt.Errorf("%w: 接收请求号 %q 与运输单 %q 的接收标记不一致", ErrCorrupt, req, r.Shipment)
917			}
918			if r.Station != sh.To {
919				return fmt.Errorf("%w: 接收请求号 %q 的接收站点 %q 与运输单 %q 目的站 %q 不一致", ErrCorrupt, req, r.Station, r.Shipment, sh.To)
920			}
921			if !sameOrder(r.Parcels, sh.Parcels) {
922				return fmt.Errorf("%w: 接收请求号 %q 的成员与运输单 %q 的原成员不一致", ErrCorrupt, req, r.Shipment)
923			}
924			for _, pid := range r.Parcels {
925				p, ok := l.Parcels[pid]
926				if !ok {
927					return fmt.Errorf("%w: 接收请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, pid)
928				}
929				found := false
930				for _, e := range p.Trail {
931					if e.Op == "接收" && e.Request == req {
932						found = true
933						break
934					}
935				}
936				if !found {
937					return fmt.Errorf("%w: 接收请求号 %q 的成员包裹 %q 缺少对应的接收轨迹", ErrCorrupt, req, pid)
938				}
939			}
940		}
941		// 冻结/解除冻结：先遍历轨迹核对冻结与解除必须成对出现、顺序正确，
942		// 再核对两张结果表与包裹当前状态的对应关系。
943		openIncident := make(map[string]string) // 包裹 -> 当前未解除的异常单号（由轨迹推导）
944		for id, p := range l.Parcels {
945			var open string
946			for i, e := range p.Trail {
947				switch e.Op {
948				case "冻结":
949					if open != "" {
950						return fmt.Errorf("%w: 包裹 %q 第 %d 条冻结时异常单 %q 尚未解除，一件包裹同时只能有一张未解除异常单",
951							ErrCorrupt, id, i+1, open)
952					}
953					open = e.Incident
954				case "解除冻结":
955					if open != e.Incident {
956						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除的异常单 %q 与当前冻结 %q 不匹配",
957							ErrCorrupt, id, i+1, e.Incident, open)
958					}
959					open = ""
960				}
961			}
962			if p.Status == statusFrozen && open == "" {
963				return fmt.Errorf("%w: 包裹 %q 当前为异常冻结，但轨迹中没有未解除的冻结记录", ErrCorrupt, id)
964			}
965			if p.Status != statusFrozen && open != "" {
966				return fmt.Errorf("%w: 包裹 %q 当前状态为 %q，但异常单 %q 尚未解除", ErrCorrupt, id, p.Status, open)
967			}
968			if open != "" {
969				openIncident[id] = open
970			}
971		}
972		for no, f := range l.Freezes {
973			if f == nil || no != f.Incident || f.Parcel == "" || f.Station == "" || f.Reason == "" || f.Time.IsZero() {
974				return fmt.Errorf("%w: 异常单号 %q 的冻结结果不完整", ErrCorrupt, no)
975			}
976			p, ok := l.Parcels[f.Parcel]
977			if !ok {
978				return fmt.Errorf("%w: 异常单 %q 引用了不存在的包裹 %q", ErrCorrupt, no, f.Parcel)
979			}
980			if f.ReleasedBy == "" && p.Station != f.Station {
981				return fmt.Errorf("%w: 异常单 %q 记录的站点 %q 与包裹 %q 当前站点 %q 不一致",
982					ErrCorrupt, no, f.Station, f.Parcel, p.Station)
983			}
984			if f.ReleasedBy != "" {
985				u, ok := l.Unfreezes[f.ReleasedBy]
986				if !ok || u == nil || u.Incident != no || u.Parcel != f.Parcel {
987					return fmt.Errorf("%w: 异常单 %q 标记的解除请求号 %q 无法对应", ErrCorrupt, no, f.ReleasedBy)
988				}
989			}
990		}
991		activeByParcel := make(map[string]string)
992		for req, u := range l.Unfreezes {
993			if u == nil || req != u.Request || u.Incident == "" || u.Parcel == "" || u.Note == "" || u.Time.IsZero() {
994				return fmt.Errorf("%w: 解除请求号 %q 的解除结果不完整", ErrCorrupt, req)
995			}
996			f, ok := l.Freezes[u.Incident]
997			if !ok || f == nil {
998				return fmt.Errorf("%w: 解除请求号 %q 引用了不存在的异常单 %q", ErrCorrupt, req, u.Incident)
999			}
1000			if f.Parcel != u.Parcel {
1001				return fmt.Errorf("%w: 解除请求号 %q 与异常单 %q 对应的包裹不一致", ErrCorrupt, req, u.Incident)
1002			}
1003			if f.ReleasedBy != req {
1004				return fmt.Errorf("%w: 解除请求号 %q 与异常单 %q 的解除标记不一致", ErrCorrupt, req, u.Incident)
1005			}
1006		}
1007		for no, f := range l.Freezes {
1008			if f.ReleasedBy != "" {
1009				continue
1010			}
1011			if other, dup := activeByParcel[f.Parcel]; dup {
1012				return fmt.Errorf("%w: 包裹 %q 同时存在两张未解除异常单 %q 与 %q", ErrCorrupt, f.Parcel, other, no)
1013			}
1014			activeByParcel[f.Parcel] = no
1015			if openIncident[f.Parcel] != no {
1016				return fmt.Errorf("%w: 包裹 %q 当前冻结对应的异常单应为 %q，与未解除异常单 %q 不匹配",
1017					ErrCorrupt, f.Parcel, openIncident[f.Parcel], no)
1018			}
1019			if p := l.Parcels[f.Parcel]; p.Status != statusFrozen {
1020				return fmt.Errorf("%w: 异常单 %q 未解除，但包裹 %q 当前状态为 %q", ErrCorrupt, no, f.Parcel, p.Status)
1021			}
1022		}
1023		return nil
1024	}
