1026	// coordinationPath 返回数据文件对应的协调文件（锁文件）路径。
1027	// 相对、绝对及含 .、.. 的写法先归一到同一绝对路径，已存在的符号链接也被解析，
1028	// 确保同一台账的不同路径写法共用同一把锁；首次创建不存在的台账同样适用。
1029	func coordinationPath(path string) (string, error) {
1030		abs, err := filepath.Abs(path)
1031		if err != nil {
1032			return "", fmt.Errorf("解析数据文件路径失败: %w", err)
1033		}
1034		if resolved, err := filepath.EvalSymlinks(abs); err == nil {
1035			abs = resolved
1036		} else if dir, derr := filepath.EvalSymlinks(filepath.Dir(abs)); derr == nil {
1037			abs = filepath.Join(dir, filepath.Base(abs))
1038		}
1039		return abs + ".lock", nil
1040	}
1041	
1042	// OpenForUpdate 在进程间排他协调下打开台账，供会改写台账的命令使用：
1043	// 先取得该台账的锁（其他终端正在作业时等待其完成），再在锁内读取最新已提交
1044	// 数据；调用方随后完成的受理、去重与整次保存都在最新数据上进行，并行效果
1045	// 等同于某个逐次执行顺序。返回的 release 必须在本次命令结束时调用（无论成败）。
1046	// 锁由操作系统随文件描述符管理，持有者进程被强制终止时自动释放，
1047	// 无需人工删除协调文件即可继续作业。
1048	func OpenForUpdate(path string) (s *Store, release func(), err error) {
1049		lockPath, err := coordinationPath(path)
1050		if err != nil {
1051			return nil, nil, err
1052		}
1053		if err := os.MkdirAll(filepath.Dir(lockPath), 0o755); err != nil {
1054			return nil, nil, fmt.Errorf("准备协调文件失败: %w", err)
1055		}
1056		lock, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0o644)
1057		if err != nil {
1058			return nil, nil, fmt.Errorf("打开协调文件失败: %w", err)
1059		}
1060		if err := syscall.Flock(int(lock.Fd()), syscall.LOCK_EX); err != nil {
1061			_ = lock.Close()
1062			return nil, nil, fmt.Errorf("等待台账协调锁失败: %w", err)
1063		}
1064		release = func() {
1065			_ = syscall.Flock(int(lock.Fd()), syscall.LOCK_UN)
1066			_ = lock.Close()
1067		}
1068		s, err = Open(path)
1069		if err != nil {
1070			release()
1071			return nil, nil, err
1072		}
1073		return s, release, nil
1074	}
