1794	// 及其回执完全保留，即使它们已进入其他批次或被冻结也不阻止中止，不检查也不改变
1795	// 其当前状态。全部满足时按原成员顺序将全部未回执件恢复“在站”（站点为出发站），
1796	// 各追加一条含批次、中止请求号、原因、站点和时间的收回记录；收回不是失败回执，
1797	// 批次回执记录不变。中止永久关闭原批次，原成员顺序、配送员与出站时间保留不变。
1798	// 收回算新的流转，收回后不能退回出站前的旧交接；收回件可交接、冻结或再次出站，
1799	// 但不能首次回执旧批次（receipt 与 receipt-import 同样遵守）。
1800	// 中止请求号独立去重，可与批次号、包裹号及其他业务编号同名：相同请求号且批次、
1801	// 清理后的原因相同，直接返回首次收回集合与时间，replayed 为 true，不重新计算成员、
1802	// 不检查当前状态、不改写台账；请求号相同但批次或原因不同报冲突。
1803	// 每批只能成功中止一次：换请求号再中止或中止已正常完成的批次均拒绝；
1804	// 失败的首次中止不占用请求号。
1805	func (s *Store) Abort(request, batch, reason string, now time.Time) (res *AbortResult, replayed bool, err error) {
1806		if saved, ok := s.data.Aborts[request]; ok {
1807			if saved.Batch == batch && saved.Reason == reason {
1808				return saved, true, nil
1809			}
1810			return nil, false, fmt.Errorf("中止请求号 %q 已用于一次不同的中止（批次=%q 原因=%q），内容冲突",
1811				request, saved.Batch, saved.Reason)
1812		}
1813	
1814		b, ok := s.data.Batches[batch]
1815		if !ok {
1816			return nil, false, fmt.Errorf("中止失败：批次号 %q 不存在", batch)
1817		}
1818		if b.AbortedBy != "" {
1819			return nil, false, fmt.Errorf("中止失败：批次 %q 已中止（中止请求号 %q），每批只能成功中止一次", batch, b.AbortedBy)
1820		}
1821		if b.TransferredBy != "" {
1822			return nil, false, fmt.Errorf("中止失败：批次 %q 已转交（续接请求号 %q），不能中止", batch, b.TransferredBy)
1823		}
1824		if b.Done() {
1825			return nil, false, fmt.Errorf("中止失败：批次 %q 已全部回执完成，不能中止", batch)
1826		}
1827	
1828		// 按原成员顺序挑出全部未回执成员（批次未完成，必至少有一件）。
1829		recalled := make([]string, 0, len(b.Parcels)-len(b.Receipts))
1830		for _, pid := range b.Parcels {
1831			if e, done := b.Receipts[pid]; !done || e.RevokedBy != "" {
1832				recalled = append(recalled, pid)
1833			}
1834		}
1835		if len(recalled) == 0 {
1836			return nil, false, fmt.Errorf("中止失败：批次 %q 没有未回执成员，不能中止", batch)
1837		}
1838	
1839		// 先做全部校验：未回执成员必须仍在原批次配送中且归属出发站，任一不符整批拒绝。
1840		for _, pid := range recalled {
1841			p := s.data.Parcels[pid] // 批次成员必已登记（载入校验保证）
1842			if p.Status != statusDelivering || currentBatch(p) != batch || p.Station != b.Station {
1843				return nil, false, fmt.Errorf("中止失败：包裹 %q 当前归属 %q、状态 %q，不在批次 %q 从出发站 %q 配送中，整批中止未执行",
1844					pid, p.Station, p.Status, batch, b.Station)
1845			}
1846		}
1847	
1848		res = &AbortResult{
1849			Request: request,
1850			Batch:   batch,
1851			Station: b.Station,
1852			Reason:  reason,
1853			Parcels: recalled,
1854			Time:    now,
1855		}
1856		s.data.Aborts[request] = res
1857		b.AbortedBy = request
1858	
1859		// 记录旧值，落盘失败时整体回滚。
1860		prev := make(map[string]struct {
1861			status string
1862			trail  []Event
1863		}, len(recalled))
1864		for _, pid := range recalled {
1865			p := s.data.Parcels[pid]
1866			prev[pid] = struct {
1867				status string
1868				trail  []Event
1869			}{p.Status, append([]Event(nil), p.Trail...)}
1870			p.Status = statusInStation // 实物已收回出发站，站点仍记出发站
1871			p.Trail = append(p.Trail, Event{
1872				Op:      "收回",
1873				Station: b.Station,
1874				Batch:   batch,
1875				Request: request,
1876				Reason:  reason,
1877				Time:    now,
1878			})
1879		}
1880	
1881		if err := s.save(); err != nil {
1882			delete(s.data.Aborts, request)
1883			b.AbortedBy = ""
1884			for pid, old := range prev {
1885				p := s.data.Parcels[pid]
1886				p.Status = old.status
1887				p.Trail = old.trail
1888			}
1889			return nil, false, err
1890		}
1891		return res, false, nil
1892	}
