12	func mustShip(t *testing.T, s *Store, shipment, from, to string, parcels []string, now time.Time) *ShipmentResult {
13		t.Helper()
14		res, replayed, err := s.Ship(shipment, from, to, parcels, now)
15		if err != nil || replayed {
16			t.Fatalf("Ship(%q) 意外失败: %v replayed=%v", shipment, err, replayed)
17		}
18		return res
19	}
