21	func mustReceive(t *testing.T, s *Store, request, shipment, station string, now time.Time) *ReceiveResult {
22		t.Helper()
23		res, replayed, err := s.Receive(request, shipment, station, now)
24		if err != nil || replayed {
25			t.Fatalf("Receive(%q) 意外失败: %v replayed=%v", request, err, replayed)
