38	func TestShipSuccess(t *testing.T) {
39		s, _ := openTempStore(t)
40		setupShipBase(t, s)
41	
42		shipTime := tClock(2026, 10, 5, 10, 0)
43		res := mustShip(t, s, "S1", "站点A", "站点B", []string{"P002", "P001"}, shipTime)
44		if res.Shipment != "S1" || res.From != "站点A" || res.To != "站点B" || !res.Time.Equal(shipTime) {
45			t.Fatalf("发运结果不符: %+v", res)
46		}
47		// 成员按首次提交顺序永久保存。
48		if !sameOrder(res.Parcels, []string{"P002", "P001"}) {
49			t.Fatalf("成员顺序应为首次提交顺序: %v", res.Parcels)
50		}
51		if res.ReceivedBy != "" {
52			t.Fatalf("新运输单不应标记已接收: %+v", res)
53		}
54		for _, id := range []string{"P001", "P002"} {
55			p, err := s.Query(id)
56			if err != nil {
57				t.Fatalf("Query(%q) 失败: %v", id, err)
58			}
59			if p.Status != statusInTransit {
60				t.Fatalf("包裹 %q 状态应为站间在途，得到 %q", id, p.Status)
61			}
62			if p.Station != "站点A" {
63				t.Fatalf("在途包裹 %q 归属站点应暂记源站，得到 %q", id, p.Station)
64			}
65			last := p.Trail[len(p.Trail)-1]
66			if last.Op != "发运" || last.Shipment != "S1" || last.From != "站点A" || last.To != "站点B" || !last.Time.Equal(shipTime) {
67				t.Fatalf("包裹 %q 缺少含运输单、两站和时间的发运轨迹: %+v", id, last)
68			}
69			// 在途包裹应能查到当前运输单。
70			if sh := s.ActiveShipment(id); sh == nil || sh.Shipment != "S1" {
71				t.Fatalf("包裹 %q 应属于未接收运输单 S1", id)
72			}
73		}
74	}
