76	func TestShipReplayAndConflict(t *testing.T) {
77		s, _ := openTempStore(t)
78		setupShipBase(t, s)
79		shipTime := tClock(2026, 10, 5, 10, 0)
80		mustShip(t, s, "S1", "站点A", "站点B", []string{"P001", "P002"}, shipTime)
81	
82		// 同号、同两站、同集合（换序）重放：返回首次成员顺序与发运时间，不追加轨迹。
83		res, replayed, err := s.Ship("S1", "站点A", "站点B", []string{"P002", "P001"}, tClock(2026, 10, 5, 11, 0))
84		if err != nil || !replayed {
85			t.Fatalf("同内容重放应返回首次结果: %v replayed=%v", err, replayed)
86		}
87		if !sameOrder(res.Parcels, []string{"P001", "P002"}) || !res.Time.Equal(shipTime) {
88			t.Fatalf("重放应返回首次成员顺序与发运时间: %+v", res)
89		}
90		p, _ := s.Query("P001")
91		if len(p.Trail) != 2 {
92			t.Fatalf("重放不应追加轨迹，得到 %d 条", len(p.Trail))
93		}
94	
95		// 换内容冲突：换目的站、换源站、换集合均拒绝。
96		for _, tc := range []struct {
97			from, to string
98			parcels  []string
99		}{
100			{"站点A", "站点C", []string{"P001", "P002"}},
101			{"站点C", "站点B", []string{"P001", "P002"}},
102			{"站点A", "站点B", []string{"P001"}},
103		} {
104			if _, _, err := s.Ship("S1", tc.from, tc.to, tc.parcels, tClock(2026, 10, 5, 11, 0)); err == nil ||
105				!strings.Contains(err.Error(), "冲突") {
106				t.Fatalf("换内容应报冲突: from=%q to=%q parcels=%v err=%v", tc.from, tc.to, tc.parcels, err)
107			}
108		}
109	
110		// 接收后运输单号也不释放：同号重放仍返回首次结果，换内容仍冲突。
111		mustReceive(t, s, "RS1", "S1", "站点B", tClock(2026, 10, 5, 12, 0))
112		if _, replayed, err := s.Ship("S1", "站点A", "站点B", []string{"P002", "P001"}, tClock(2026, 10, 5, 13, 0)); err != nil || !replayed {
113			t.Fatalf("接收后同内容重放仍应返回首次结果: %v replayed=%v", err, replayed)
114		}
115		if _, _, err := s.Ship("S1", "站点A", "站点C", []string{"P001", "P002"}, tClock(2026, 10, 5, 13, 0)); err == nil {
116			t.Fatalf("接收后换内容仍应报冲突")
117		}
118	}
