120	func TestShipFailuresAtomic(t *testing.T) {
121		s, _ := openTempStore(t)
122		setupShipBase(t, s)
123		mustRegister(t, s, "P003", "站点C", tClock(2026, 10, 5, 9, 0))
124		mustRegister(t, s, "P004", "站点A", tClock(2026, 10, 5, 9, 0))
125		mustFreeze(t, s, "E1", "P004", "站点A", "外包装破损", tClock(2026, 10, 5, 9, 30))
126		mustRegister(t, s, "P005", "站点A", tClock(2026, 10, 5, 9, 0))
127		mustDispatch(t, s, "B1", "站点A", "张三", []string{"P005"}, tClock(2026, 10, 5, 9, 40))
128	
129		// 未登记、不在源站、已冻结、配送中：任一不符整单拒绝。
130		for _, parcels := range [][]string{
131			{"P001", "P404"},
132			{"P001", "P003"},
133			{"P001", "P004"},
134			{"P001", "P005"},
135		} {
136			if _, _, err := s.Ship("SX", "站点A", "站点B", parcels, tClock(2026, 10, 5, 10, 0)); err == nil {
137				t.Fatalf("含不符成员 %v 的发运应整单拒绝", parcels)
138			}
139		}
140		// 整单拒绝：其余包裹状态与轨迹不变，运输单号不占用。
141		for _, id := range []string{"P001", "P002"} {
142			p, _ := s.Query(id)
143			if p.Status != statusInStation || p.Station != "站点A" || len(p.Trail) != 1 {
144				t.Fatalf("失败的首次发运不应改变包裹 %q: status=%q station=%q trail=%d", id, p.Status, p.Station, len(p.Trail))
145			}
146		}
147		if _, err := s.ShipmentQuery("SX"); err == nil {
148			t.Fatalf("失败的首次发运不应占用运输单号")
149		}
150	
151		// 在途件不能再次发运（每件同时最多属于一张未接收运输单）。
152		mustShip(t, s, "S1", "站点A", "站点B", []string{"P001"}, tClock(2026, 10, 5, 10, 0))
153		if _, _, err := s.Ship("S2", "站点A", "站点C", []string{"P001", "P002"}, tClock(2026, 10, 5, 10, 30)); err == nil {
154			t.Fatalf("在途件应不能再次发运")
155		}
156		p2, _ := s.Query("P002")
157		if p2.Status != statusInStation || len(p2.Trail) != 1 {
158			t.Fatalf("整单拒绝不应改变其他包裹: %+v", p2)
159		}
160		if _, err := s.ShipmentQuery("S2"); err == nil {
161			t.Fatalf("失败的首次发运不应占用运输单号 S2")
162		}
163	}
