257		})
258		corruptLedger(t, path2, raw2, "交接后无记录的状态改变", func(m map[string]any) {
259			ledgerParcel(m, "P001")["status"] = "配送中"
260		})
261		restoreLedger(t, path2, raw2)
262	}
263	
264	// 合法后续流转（交接、再次发运与接收、配送回执及其撤销、中止、续接、冻结与解除）
265	// 重新载入后仍应受理，并按这些记录形成的当前站点、状态和运输归属校验；
266	// 历史接收不把成员固定在目的站；发运、接收同内容重放仍返回首次结果且不改写文件。
267	func TestPostReceiveFlowsAndReplaySurviveReload(t *testing.T) {
268		s, path := openTempStore(t)
269		setupShipBase(t, s)
270		mustRegister(t, s, "P003", "站点B", tClock(2026, 10, 5, 9, 0))
271		mustRegister(t, s, "P004", "站点B", tClock(2026, 10, 5, 9, 0))
272	
273		shipTime := tClock(2026, 10, 5, 10, 0)
274		recvTime := tClock(2026, 10, 5, 12, 0)
275		mustShip(t, s, "S1", "站点A", "站点B", []string{"P001", "P002"}, shipTime)
276		mustReceive(t, s, "RS1", "S1", "站点B", recvTime)
277	
278		// P001：交接 B->C，再次发运 C->D 并接收，最终归站点D 在站。
279		mustHandoff(t, s, "R2", "站点B", "站点C", []string{"P001"}, tClock(2026, 10, 5, 13, 0))
280		mustShip(t, s, "S2", "站点C", "站点D", []string{"P001"}, tClock(2026, 10, 5, 14, 0))
281		mustReceive(t, s, "RS2", "S2", "站点D", tClock(2026, 10, 5, 15, 0))
282	
283		// P002：出站 -> 失败回执 -> 撤销 -> 签收。
284		mustDispatch(t, s, "B1", "站点B", "张三", []string{"P002"}, tClock(2026, 10, 5, 13, 0))
285		mustReceiptOK(t, s, "RC1", "B1", "P002", "失败", "收件人不在", tClock(2026, 10, 5, 14, 0))
286		mustRevoke(t, s, "RV1", "RC1", "误录失败，实际仍配送中", tClock(2026, 10, 5, 15, 0))
287		mustReceiptOK(t, s, "RC2", "B1", "P002", "签收", "", tClock(2026, 10, 5, 16, 0))
288	
289		// P003：出站 -> 中止收回 -> 冻结 -> 解除。
290		mustDispatch(t, s, "B2", "站点B", "张三", []string{"P003"}, tClock(2026, 10, 5, 13, 0))
291		mustAbort(t, s, "A1", "B2", "车辆故障全部收回", tClock(2026, 10, 5, 14, 0))
292		mustFreeze(t, s, "E1", "P003", "站点B", "外包装破损", tClock(2026, 10, 5, 15, 0))
293		if _, _, err := s.Unfreeze("U1", "E1", "已核实放行", tClock(2026, 10, 5, 16, 0)); err != nil {
294			t.Fatalf("Unfreeze 意外失败: %v", err)
295		}
296	
297		// P004：出站 -> 续接给另一配送员。
298		mustDispatch(t, s, "B3", "站点B", "张三", []string{"P004"}, tClock(2026, 10, 5, 13, 0))
299		mustTransfer(t, s, "T1", "B3", "B4", "李四", "原配送员车辆故障", tClock(2026, 10, 5, 14, 0))
300	
301		before, err := os.ReadFile(path)
302		if err != nil {
303			t.Fatal(err)
304		}
305	
306		// 重新载入：合法后续流转形成的当前站点、状态与运输归属必须被接受。
307		s2, err := Open(path)
308		if err != nil {
309			t.Fatalf("重新载入合法台账失败: %v", err)
310		}
311		p1, _ := s2.Query("P001")
312		if p1.Station != "站点D" || p1.Status != statusInStation {
313			t.Fatalf("P001 应归站点D 在站（历史接收不固定在目的站）: %+v", p1)
314		}
315		p2, _ := s2.Query("P002")
316		if p2.Station != "站点B" || p2.Status != statusSigned {
317			t.Fatalf("P002 应在站点B 已签收: %+v", p2)
318		}
319		p3, _ := s2.Query("P003")
320		if p3.Station != "站点B" || p3.Status != statusInStation {
321			t.Fatalf("P003 应在站点B 在站: %+v", p3)
322		}
323		p4, _ := s2.Query("P004")
324		if p4.Station != "站点B" || p4.Status != statusDelivering || currentBatch(p4) != "B4" {
325			t.Fatalf("P004 应在批次 B4 配送中: %+v", p4)
326		}
327	
328		// 发运、接收同内容重放：返回首次成员顺序与时间，不重新检查首次受理条件。
329		res1, replayed, err := s2.Ship("S1", "站点A", "站点B", []string{"P002", "P001"}, tClock(2026, 10, 6, 9, 0))
330		if err != nil || !replayed || !sameOrder(res1.Parcels, []string{"P001", "P002"}) || !res1.Time.Equal(shipTime) {
331			t.Fatalf("发运重放应返回首次成员顺序与时间: %+v replayed=%v err=%v", res1, replayed, err)
332		}
333		res2, replayed, err := s2.Receive("RS1", "S1", "站点B", tClock(2026, 10, 6, 9, 0))
334		if err != nil || !replayed || !sameOrder(res2.Parcels, []string{"P001", "P002"}) || !res2.Time.Equal(recvTime) {
335			t.Fatalf("接收重放应返回首次成员与时间: %+v replayed=%v err=%v", res2, replayed, err)
336		}
337		if _, replayed, err := s2.Ship("S2", "站点C", "站点D", []string{"P001"}, tClock(2026, 10, 6, 9, 0)); err != nil || !replayed {
338			t.Fatalf("再次发运的重放应返回首次结果: replayed=%v err=%v", replayed, err)
339		}
340		if _, replayed, err := s2.Receive("RS2", "S2", "站点D", tClock(2026, 10, 6, 9, 0)); err != nil || !replayed {
341			t.Fatalf("再次接收的重放应返回首次结果: replayed=%v err=%v", replayed, err)
342		}
343		// 接收后运输单号不释放：换内容仍冲突。
344		if _, _, err := s2.Ship("S1", "站点A", "站点C", []string{"P001"}, tClock(2026, 10, 6, 9, 0)); err == nil {
345			t.Fatalf("接收后同号换内容仍应报冲突")
346		}
347	
348		// 重放不追加轨迹、不改写文件。
349		p1After, _ := s2.Query("P001")
350		if len(p1After.Trail) != len(p1.Trail) {
351			t.Fatalf("重放不应追加轨迹: %d -> %d", len(p1.Trail), len(p1After.Trail))
352		}
353		after, err := os.ReadFile(path)
354		if err != nil {
355			t.Fatal(err)
356		}
357		if string(before) != string(after) {
358			t.Fatalf("重放不应改写数据文件")
359		}
360	
361		// 重新载入后仍可继续受理新业务：P001 从站点D 再次发运。
362		if _, _, err := s2.Ship("S3", "站点D", "站点E", []string{"P001"}, tClock(2026, 10, 6, 10, 0)); err != nil {
363			t.Fatalf("重新载入后继续发运失败: %v", err)
364		}
365		s3, err := Open(path)
366		if err != nil {
367			t.Fatalf("再次载入失败: %v", err)
368		}
369		p1Final, _ := s3.Query("P001")
370		if p1Final.Status != statusInTransit || p1Final.Station != "站点D" {
371			t.Fatalf("P001 应在 S3 在途、归属暂记站点D: %+v", p1Final)
372		}
373		if sh := s3.ActiveShipment("P001"); sh == nil || sh.Shipment != "S3" {
374			t.Fatalf("P001 当前运输单应为 S3")
375		}
376	}
377	
378	// 运输矛盾必须拒绝所有入口（查询、修改、历史重放），即使当前操作针对另一包裹：
379	// 标准错误说明损坏原因、退出码 1、不崩溃、不报告成功、不改写文件、新编号不占用；
380	// 还原有效文件后可用同一新号重试。
381	func TestCorruptShipmentLedgerBlocksAllEntries(t *testing.T) {
382		s, path := openTempStore(t)
383		setupShipBase(t, s)
384		mustRegister(t, s, "P005", "站点A", tClock(2026, 10, 5, 9, 0)) // 与运输无关的包裹
385		mustShip(t, s, "S1", "站点A", "站点B", []string{"P001", "P002"}, tClock(2026, 10, 5, 10, 0))
386		mustReceive(t, s, "RS1", "S1", "站点B", tClock(2026, 10, 5, 12, 0))
387		raw, err := os.ReadFile(path)
388		if err != nil {
389			t.Fatal(err)
390		}
391	
392		// 写入损坏台账：接收轨迹位于发运之前。
393		var m map[string]any
394		if err := json.Unmarshal(raw, &m); err != nil {
395			t.Fatal(err)
396		}
397		trail := ledgerParcel(m, "P001")["trail"].([]any)
398		trail[1], trail[2] = trail[2], trail[1]
399		corrupt, err := json.Marshal(m)
400		if err != nil {
401			t.Fatal(err)
402		}
403		if err := os.WriteFile(path, corrupt, 0o644); err != nil {
404			t.Fatal(err)
405		}
406	
407		entries := [][]string{
408			{"query", "--id", "P005"},                        // 查询：针对另一包裹也必须拒绝
409			{"query", "--id", "P001"},                        // 查询：当事包裹
410			{"shipment", "--id", "S1"},                       // 运输单查询
411			{"register", "--id", "P006", "--station", "站点A"}, // 修改
412			{"ship", "--shipment", "S9", "--from", "站点A", "--to", "站点B", "--parcel", "P005"},                     // 修改：新运输单号
413			{"receive", "--request", "RS1", "--shipment", "S1", "--station", "站点B"},                              // 历史重放
414			{"ship", "--shipment", "S1", "--from", "站点A", "--to", "站点B", "--parcel", "P001", "--parcel", "P002"}, // 历史重放
415		}
416		for _, args := range entries {
417			stdout, stderr, code := runCLI(t, path, args...)
418			if code != exitBusiness {
419				t.Fatalf("%v 应以状态码 1 拒绝，得到 code=%d out=%s", args, code, stdout)
420			}
421			if !strings.Contains(stderr, "数据文件已损坏") {
422				t.Fatalf("%v 标准错误应说明损坏原因，得到: %s", args, stderr)
423			}
424			if strings.Contains(stdout, "成功") {
425				t.Fatalf("%v 不得报告成功: %s", args, stdout)
426			}
427		}
428	
429		// 不自动修补或覆盖台账：原文件字节不变，新业务编号不占用。
430		got, err := os.ReadFile(path)
431		if err != nil {
432			t.Fatal(err)
433		}
434		if string(got) != string(corrupt) {
435			t.Fatalf("损坏文件不得被改写")
436		}
437	
438		// 还原有效文件后可用同一新号重试。
439		restoreLedger(t, path, raw)
440		out, _, code := runCLI(t, path, "ship", "--shipment", "S9", "--from", "站点A", "--to", "站点B", "--parcel", "P005")
441		if code != 0 || !strings.Contains(out, "发运成功") {
442			t.Fatalf("还原后同一新号重试应成功: code=%d out=%s", code, out)
443		}
444		out, _, code = runCLI(t, path, "register", "--id", "P006", "--station", "站点A")
445		if code != 0 || !strings.Contains(out, "收件登记成功") {
446			t.Fatalf("还原后登记应成功: code=%d out=%s", code, out)
447		}
448	}
449	
450	// 有效台账上的发运、接收重放不重新检查首次受理条件：即使包裹已不满足
451	// 首次发运条件（在源站在站），同内容重放仍返回首次结果。
452	func TestShipReceiveReplayDoesNotRecheckAcceptance(t *testing.T) {
453		s, _ := openTempStore(t)
454		setupShipBase(t, s)
455		shipTime := tClock(2026, 10, 5, 10, 0)
456		mustShip(t, s, "S1", "站点A", "站点B", []string{"P001"}, shipTime)
457		recvTime := tClock(2026, 10, 5, 12, 0)
458		mustReceive(t, s, "RS1", "S1", "站点B", recvTime)
459		// 接收后包裹离开目的站，不再满足“在源站在站”的首次发运条件。
460		mustHandoff(t, s, "R2", "站点B", "站点C", []string{"P001"}, tClock(2026, 10, 5, 13, 0))
461	
462		res, replayed, err := s.Ship("S1", "站点A", "站点B", []string{"P001"}, time.Now())
463		if err != nil || !replayed || !res.Time.Equal(shipTime) {
464			t.Fatalf("发运重放不应重新检查首次受理条件: %+v replayed=%v err=%v", res, replayed, err)
465		}
466		rres, replayed, err := s.Receive("RS1", "S1", "站点B", time.Now())
467		if err != nil || !replayed || !rres.Time.Equal(recvTime) {
468			t.Fatalf("接收重放不应重新检查首次受理条件: %+v replayed=%v err=%v", rres, replayed, err)
469		}
470		p, _ := s.Query("P001")
471		if p.Station != "站点C" || len(p.Trail) != 4 {
472			t.Fatalf("重放不应移动包裹或追加轨迹: %+v", p)
473		}
474	}
