284	// 持有协调锁的进程被强制终止（相当于文件描述符被直接关闭）后，
285	// 其他终端无需人工删除协调文件即可继续作业。
286	func TestLockReleasedAfterAbruptTermination(t *testing.T) {
287		dbPath := filepath.Join(t.TempDir(), "ledger.json")
288		lockPath, err := coordinationPath(dbPath)
289		if err != nil {
290			t.Fatalf("coordinationPath 失败: %v", err)
291		}
292		if err := os.MkdirAll(filepath.Dir(lockPath), 0o755); err != nil {
293			t.Fatalf("建目录失败: %v", err)
294		}
295		// 模拟另一个进程持锁后被 kill -9：锁随描述符关闭由系统释放，协调文件仍在。
296		f, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0o644)
297		if err != nil {
298			t.Fatalf("打开协调文件失败: %v", err)
299		}
300		if err := syscall.Flock(int(f.Fd()), syscall.LOCK_EX); err != nil {
301			t.Fatalf("加锁失败: %v", err)
302		}
303		_ = f.Close() // 进程终止：不主动解锁、不删除协调文件
304	
305		if _, _, code := runCLI(t, dbPath, "register", "--id", "P001", "--station", "站点A"); code != 0 {
306			t.Fatalf("持有者异常终止后应无需人工清理即可继续登记: code=%d", code)
307		}
308	}
