310	// query 不加锁、不改写数据文件，也不会产生协调文件。
311	func TestQueryDoesNotTouchFiles(t *testing.T) {
312		dbPath := filepath.Join(t.TempDir(), "ledger.json")
313		if _, _, code := runCLI(t, dbPath, "register", "--id", "P001", "--station", "站点A"); code != 0 {
314			t.Fatalf("登记失败")
315		}
316		before, err := os.ReadFile(dbPath)
317		if err != nil {
318			t.Fatalf("读取数据文件失败: %v", err)
319		}
320		if _, _, code := runCLI(t, dbPath, "query", "--id", "P001"); code != 0 {
321			t.Fatalf("查询失败")
322		}
323		after, err := os.ReadFile(dbPath)
324		if err != nil {
325			t.Fatalf("读取数据文件失败: %v", err)
326		}
327		if string(before) != string(after) {
328			t.Fatalf("查询不得改写数据文件")
329		}
330	
331		// 对不存在的台账查询：既不建数据文件也不建协调文件。
332		ghost := filepath.Join(t.TempDir(), "ghost.json")
333		if _, _, code := runCLI(t, ghost, "query", "--id", "P001"); code != exitBusiness {
334			t.Fatalf("查询不存在的包裹应以 1 退出，得到 %d", code)
335		}
336		if _, err := os.Stat(ghost); !os.IsNotExist(err) {
337			t.Fatalf("查询不得创建数据文件")
338		}
339		lockPath, _ := coordinationPath(ghost)
340		if _, err := os.Stat(lockPath); !os.IsNotExist(err) {
341			t.Fatalf("查询不得创建协调文件")
342		}
343	}
