	}
	// 全部接收后新请求拒绝（两种方式都拒绝），运输单号不释放。
	if _, _, err := s.Receive("RS9", "S1", "站点B", nil, tClock(2026, 10, 5, 15, 0)); err == nil {
		t.Fatalf("全部接收后不选成员的新请求应拒绝")
	}
