	if _, replayed, err := s.Ship("S1", "站点A", "站点B", []string{"P003", "P002", "P001"}, tClock(2026, 10, 5, 16, 0)); err != nil || !replayed {
		t.Fatalf("全部接收后运输单号不释放，同内容发运应重放: %v replayed=%v", err, replayed)
